# 系統的 /usr/bin/python3 才有 apt 裝的 GTK / WebKit 綁定；pyenv / conda 的 python3 排在 PATH 前面時要跳過它。
BACKEND=""
PY=""
has_gtk() {
  "$1" - <<'PYCHK' >/dev/null 2>&1
import gi
gi.require_version('Gtk', '3.0')
ok = False
for v in ('4.1', '4.0'):
    try:
        gi.require_version('WebKit2', v); ok = True; break
