  [ -x /usr/bin/python3 ] && echo /usr/bin/python3
  command -v python3 2>/dev/null || true
  ls /usr/bin/python3.[0-9]* 2>/dev/null | grep -v config || true
}
check_deps() {
  local want_qt=0 c
  for a in "${PASS[@]+"${PASS[@]}"}"; do [ "$a" = --qt ] && want_qt=1; done
