  if [ "$(readlink -f "$0")" != "$HOST_DIR/pilcrow-app.sh" ]; then cp "$0" "$HOST_DIR/pilcrow-app.sh"; fi
  chmod +x "$HOST_DIR/pilcrow-app.sh"
  mkdir -p "$APPS_DIR" "$HOME/.local/bin"
