export const terminals = new EventEmitter();
const all = new Map();

let nodePty;
function loadNodePty() {
  if (nodePty !== undefined) return nodePty;
  try {
    nodePty = require('node-pty');
  } catch {
    nodePty = null;
  }
  return nodePty;
}

