        <Toasts />
      </main>
      {panelOpen && <Resizer side="right" onResize={resizePanel} />}
      <Slot open={panelOpen} side="right" className="panel-shell">
        {panelSession && <RightPanel key={panelSession.id} session={panelSession} />}
