      tried = sessionStorage.getItem('pilcrow.reloadedFor') || '';
    } catch {
      /* storage unavailable */
    }
    if (tried === server) return;
    const t = setTimeout(() => {
      try {
        sessionStorage.setItem('pilcrow.reloadedFor', server!);
      } catch {
