}

export function truncate(s: string, n: number): string {
  if (!s) return '';
  return s.length > n ? s.slice(0, n - 1) + '…' : s;
}

export function firstLine(s: string): string {
  return (s || '').split('\n')[0];
}

export function plural(n: number, one: string, many = one + 's') {
