}

.side-new,
.side-search {
  display: flex;
  align-items: center;
  gap: 9px;
  height: 30px;
  padding: 0 8px;
  border-radius: var(--r-2);
  color: var(--text-2);
  font-size: var(--fs-ui);
  text-align: left;
  transition: background var(--t-fast), color var(--t-fast);
}
.side-new:hover {
  background: var(--fill-2);
  color: var(--text);
}
.side-new:active {
  background: var(--fill-3);
}
.side-kbd {
