}
.side-search:focus-within {
  background: var(--fill-2);
  color: var(--text-2);
}
.side-search input {
  flex: 1;
  min-width: 0;
  border: none;
  outline: none;
  background: transparent;
  font-size: var(--fs-ui);
}
.side-search input::placeholder {
  color: var(--text-3);
}
.side-match {
  background: none;
  color: var(--text);
  font-weight: 600;
  text-decoration: underline;
  text-decoration-color: var(--accent);
  text-decoration-thickness: 1.5px;
  text-underline-offset: 3px;
}
.side-search button {
  flex: none;
  display: grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  color: var(--text-3);
}
.side-search button:hover {
  background: var(--fill-2);
}

.side-list {
  flex: 1;
  overflow-y: auto;
  padding: 2px 10px 14px;
  mask-image: linear-gradient(to bottom, transparent 0, #000 8px, #000 calc(100% - 16px), transparent);
}

.side-group {
  margin-top: 14px;
}
.side-section-label {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 24px;
  padding: 0 8px;
  font-size: var(--fs-micro);
  font-weight: 600;
  color: var(--text-3);
}
.section.accent .side-section-label {
  color: var(--accent-text);
}
.side-count {
  display: inline-grid;
  place-items: center;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 8px;
  font-size: 10.5px;
  font-weight: 650;
  color: var(--accent-ink);
  background: var(--accent);
}

.side-group-head {
  display: flex;
  align-items: center;
  height: 24px;
  border-radius: var(--r-2);
}
.side-group-toggle {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 4px;
  height: 24px;
  padding: 0 8px;
  font-size: var(--fs-micro);
  font-weight: 600;
  color: var(--text-3);
  text-align: left;
  transition: color var(--t-fast);
}
.side-group-toggle:hover {
  color: var(--text-2);
}
.side-group-chev {
