}

.side-row {
  position: relative;
  display: flex;
  align-items: center;
  min-height: 30px;
  border-radius: var(--r-2);
  transition: background var(--t-fast);
  animation: fade var(--t-med) var(--ease);
}
.side-row:hover,
.side-row.menu-open {
