  place-items: center end;
  min-width: 30px;
  height: 24px;
  margin-right: 4px;
  flex: none;
}
.side-row-status {
  display: flex;
  align-items: center;
  gap: 6px;
  padding-right: 4px;
  transition: opacity var(--t-fast);
}
.side-time {
  font-size: var(--fs-micro);
  color: var(--text-4);
  font-variant-numeric: tabular-nums;
}
.side-row-menu {
  position: absolute;
  right: 0;
  top: 0;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--t-fast);
}
.side-row:hover .side-row-menu,
.side-row-menu[aria-expanded='true'] {
