  padding: 8px 10px 10px;
}
.side-foot-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 28px;
  padding: 0 8px;
  border-radius: var(--r-2);
  color: var(--text-3);
  font-size: var(--fs-ui);
  transition: background var(--t-fast), color var(--t-fast);
}
.side-foot-btn:hover {
